export default function next({ previous, propertyId }) {
  const groups = [
    {
      dimension: "unifiedScreenName",
      metrics: ["screenPageViews", "activeUsers", "screenPageViewsPerUser", "eventCount"],
    },
    {
      dimension: "landingPagePlusQueryString",
      metrics: [
        "activeUsers",
        "engagedSessions",
        "engagementRate",
        "eventCount",
        "organicGoogleSearchAveragePosition",
        "organicGoogleSearchClickThroughRate",
        "organicGoogleSearchClicks",
        "organicGoogleSearchImpressions",
      ],
    },
    {
      dimension: "country",
      metrics: [
        "activeUsers",
        "newUsers",
        "engagementRate",
        "engagedSessions",
        "eventCount",
        "totalUsers",
        "sessions",
      ],
    },
  ];
  if (!/^\d+$/.test(propertyId)) throw Error("Configure GA4 property ID");
  const day = new Date().toISOString().slice(0, 10),
    s = previous ?? { index: 0, offset: 0, day, tables: [[], [], [], [], [], []] };
  if (
    !Number.isInteger(s.index) ||
    s.index < 0 ||
    s.index >= 6 ||
    !Number.isInteger(s.offset) ||
    s.offset < 0 ||
    !Array.isArray(s.tables) ||
    s.tables.length !== 6
  )
    throw Error("Invalid report state");
  const d = (n) =>
      new Date(Date.parse(s.day + "T00:00:00Z") + n * 86400000).toISOString().slice(0, 10),
    recent = s.index % 2 === 0,
    g = groups[Math.floor(s.index / 2)];
  return {
    state: s,
    propertyId,
    dateRanges: [{ startDate: d(recent ? -7 : -14), endDate: d(recent ? -1 : -8) }],
    dimensions: [g.dimension],
    metrics: g.metrics,
    offset: s.offset,
  };
}

