export default function collect({ state, report }) {
  const lens = [4, 4, 8, 8, 7, 7];
  if (!report || !Array.isArray(report.rows)) throw Error("Invalid analytics report");
  const count =
    report.rowCount == null && report.rows.length === 0 && state.offset === 0 ? 0 : report.rowCount;
  if (
    !Number.isSafeInteger(count) ||
    count < 0 ||
    state.offset + report.rows.length > count ||
    (!report.rows.length && state.offset < count)
  )
    throw Error("Invalid analytics page");
  const rows = report.rows.map((x) => {
    if (
      !Array.isArray(x.dimensionValues) ||
      x.dimensionValues.length !== 1 ||
      typeof x.dimensionValues[0] !== "string" ||
      !Array.isArray(x.metricValues) ||
      x.metricValues.length !== lens[state.index] ||
      x.metricValues.some((v) => typeof v !== "string")
    )
      throw Error("Invalid analytics row");
    return [x.dimensionValues[0], ...x.metricValues];
  });
  const tables = state.tables.map((x) => [...x]);
  tables[state.index].push(...rows);
  const offset = state.offset + rows.length,
    done = offset === count,
    index = done ? state.index + 1 : state.index;
  return {
    state: { ...state, index, offset: done ? 0 : offset, tables },
    more: index < 6,
    day: state.day,
  };
}

