export default async function reserve({ day, blog, acknowledge, resolution }, ctx) {
  const key = "ga-weekly:" + day + ":" + blog;
  if (acknowledge) {
    if (!acknowledge.startsWith("ga-weekly:") || !["confirmed", "absent"].includes(resolution))
      throw Error("Enter the exact pending report key and confirmed or absent");
    const old = await ctx.state.get(acknowledge);
    if (old?.status !== "pending") throw Error("No matching pending report");
    await ctx.state.set(acknowledge, { status: resolution === "confirmed" ? "done" : "absent" });
  }
  const old = await ctx.state.get(key);
  if (old?.status === "done") return { key, write: false };
  if (old?.status === "pending") throw Error("Inspect Baserow before retry: " + key);
  await ctx.state.set(key, { status: "pending" });
  return { key, write: true };
}

